document.addEventListener("DOMContentLoaded", () => {

    // ambil nama dari URL
    const params = new URLSearchParams(window.location.search);
    const nama = params.get("to");

    // element cover
    const coverNama = document.getElementById("nama_undangan");

    // element hero
    const heroNama = document.getElementById("nama_undangan_hero");

    // default
    let hasil = "Tamu Undangan";

    // kalau ada nama
    if (nama && nama.trim() !== "") {
        hasil = decodeURIComponent(nama);
    }

    // tampilkan ke cover
    if (coverNama) {
        coverNama.textContent = hasil;
    }

    // tampilkan ke hero
    if (heroNama) {
        heroNama.textContent = hasil;
    }

});